using namespace std;

struct Edge {
    int v,w;
};

const int INF=10000000;
const int N=210;
const int M=21000;

vector<int> adj[N];
Edge edges[M];
int head[N],edgeCount;

void addEdge(int u,int v,int w){
    edges[edgeCount]={v,w};
    adj[u].push_back(edgeCount++);
    edges[edgeCount]={u,0};
    adj[v].push_back(edgeCount++);
}

int S,T;
int dist[N],q[N*2],arc[N],gap[N],inq[N],pre[N];

int maxFlow(int s,int t){
    memset(arc,-1,sizeof(arc));
    memset(pre,-1,sizeof(pre));
    int front=0,rear=0;
    q[rear++]=t; inq[t]=1; gap[0]++;
    dist[t]=0;
    while(front<rear){
        int u=q[front++];
        for(auto i:adj[u]){
            int v=edges[i].v;
            if(!inq[v]){
                q[rear++]=v;
                inq[v]=1;
                dist[v]=dist[u]+1;
                gap[dist[v]]++;
                arc[v]=i;
            }
        }
    }
    int totalFlow=0, low=INF, u=s;
    while(dist[s]<t){
        bool pushed=false;
        for(int &i=arc[u];i!=-1;i=adj[u][i]){
            if(edges[i].w && dist[edges[i].v]+1==dist[u]){
                low=min(low,edges[i].w);
                pre[edges[i].v]=u;
                u=edges[i].v;
                if(u==t){
                    for(int v=t;v!=s;v=pre[v]){
                        int i=arc[pre[v]];
                        edges[i].w-=low;
                        edges[i^1].w+=low;
                    }
                    totalFlow+=low;
                    low=INF;
                    u=s;
                }
                pushed=true;
                break;
            }
        }
        if(pushed) continue;
        int minDist=t+1;
        for(auto i:adj[u]){
            if(edges[i].w && minDist>dist[edges[i].v]){
                minDist=dist[edges[i].v];
                arc[u]=i;
            }
        }
        gap[dist[u]]--;
        if(gap[dist[u]]==0) break;
        dist[u]=minDist+1;
        gap[dist[u]]++;
        u=pre[u];
    }
    return totalFlow;
}

char gridX[12][12], gridY[12][12];
int sci[12][12], ca[12][12], stone[62][12][12];
int dp[62][12][12][12][12];
int dir[4][2]={{-1,0},{1,0},{0,-1},{0,1}};
int n,t;

