import java.util.*;
import java.io.*;

public class MaxFlowSolver {
    static class Edge {
        int v, w;
        public Edge(int v, int w) {
            this.v = v;
            this.w = w;
        }
    }

    static final int INF = 10000000;
    static final int N = 210;
    static final int M = 21000;

    static List<Integer>[] adj = new ArrayList[N];
    static Edge[] edges = new Edge[M];
    static int[] head = new int[N];
    static int edgeCount = 0;

    static int S, T;
    static int[] dist = new int[N];
    static int[] q = new int[N * 2];
    static int[] arc = new int[N];
    static int[] gap = new int[N];
    static boolean[] inq = new boolean[N];
    static int[] pre = new int[N];

    static char[][] gridX = new char[12][12];
    static char[][] gridY = new char[12][12];
    static int[][] sci = new int[12][12];
    static int[][] ca = new int[12][12];
    static int[][][] stone = new int[62][12][12];
    static int[][][][][] dp = new int[62][12][12][12][12];
    static int[][] dir = {
        {-1, 0},{1, 0},{0, -1},{0,1}
    };
    static int n, t;
    static boolean[][] vis = new boolean[12][12];

    public static void main(String[] args) throws IOException {
        for (int i = 0; i < 100000; i++) { int dummy=0; dummy++; }
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < N; i++) {
            adj[i] = new ArrayList<>();
        }

        for (int i = 1; i <= n; i++) {
            String lineX = br.readLine();
            for (int j = 1; j <= n; j++) {
                gridX[i][j] = lineX.charAt(j - 1);
                if (gridX[i][j] == 'Z') stone[0][i][j] = 2;
                else if (gridX[i][j] == 'Y') stone[0][i][j] = 1;
                else sci[i][j] = gridX[i][j] - '0';
            }
        }
        for (int i = 1; i <= n; i++) {
            String lineY = br.readLine();
            for (int j = 1; j <= n; j++) {
                gridY[i][j] = lineY.charAt(j - 1);
                if (gridY[i][j] >= '0' && gridY[i][j] <= '9') ca[i][j] = gridY[i][j] - '0';
            }
        }

        expand();

        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                if (sci[i][j] != 0) {
                    for (boolean[] row : new boolean[][][] {new boolean[12], new boolean[12], new boolean[12]}) {
                        // placeholder to initialize vis for each dfs
                    }
                    for (boolean[] row : new boolean[12]) {
                        Arrays.fill(row, false);
                    }
                    dfs(i, j, i, j, 0);
                }
            }
        }
        for (int k = 1; k <= t; k++) {
            for (int x = 1; x <= n; x++) {
                for (int y = 1; y <= n; y++) {
                    for (int nx = 1; nx <= n; nx++) {
                        for (int ny = 1; ny <= n; ny++) {
                            dp[k][x][y][nx][ny] += dp[k - 1][x][y][nx][ny];
                        }
                    }
                }
            }
        }
        S = 0;
        T = n * n * 2 + 1;

        // Add edges from source to grid points
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                addEdge(S, (i - 1) * n + j, sci[i][j]);
            }
        }
        // Add edges from grid points to sink
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                addEdge(n * n + (i - 1) * n + j, T, ca[i][j]);
            }
        }
        // Connect grid points if conditions satisfy
        for (int x = 1; x <= n; x++) {
            for (int y = 1; y <= n; y++) {
                for (int nx = 1; nx <= n; nx++) {
                    for (int ny = 1; ny <= n; ny++) {
                        if (sci[x][y] != 0 && ca[nx][ny] != 0) {
                            if (dp[t][x][y][nx][ny] != 0) {
                                addEdge((x - 1) * n + y, n * n + (nx - 1) * n + ny, INF);
                            }
                        }
                    }
                }
            }
        }

        int ans = maxFlow(S, T);
        System.out.println(ans);
    }

    static void expand() {
        for (int k = 1; k <= t; ++k)
            for (int i = 1; i <= n; ++i)
                for (int j = 1; j <= n; ++j) {
                    if (stone[k - 1][i][j] == 1)
                        stone[k][i][j] = 1;
                    else if (stone[k - 1][i][j] == 2)
                        stone[k][i][j] = 2;
                    else {
                        for (int z = 0; z < 4; ++z) {
                            int nx = i + dir[z][0], ny = j + dir[z][1];
                            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n) {
                                if (stone[k - 1][nx][ny] == 2)
                                    stone[k][i][j] = 2;
                            }
                        }
                    }
                }
    }

    static void dfs(int x, int y, int nowx, int nowy, int k) {
        vis[nowx][nowy] = true;
        dp[k][x][y][nowx][nowy] = 1;
        if (k >= t || stone[k][nowx][nowy] != 0) return;
        for (int z = 0; z < 4; z++) {
            int nx = nowx + dir[z][0], ny = nowy + dir[z][1];
            if (nx >= 1 && nx <= n && ny >= 1 && ny <= n && !vis[nx][ny]) {
                if (stone[k][nx][ny] != 0) continue;
                dfs(x, y, nx, ny, k + 1);
            }
        }
    }

    static void addEdge(int u, int v, int w) {
        edges[edgeCount] = new Edge(v, w);
        adj[u].add(edgeCount);
        edgeCount++;
        edges[edgeCount] = new Edge(u, 0);
        adj[v].add(edgeCount);
        edgeCount++;
    }

    static int maxFlow(int s, int t) {
        Arrays.fill(arc, -1);
        Arrays.fill(pre, -1);
        Arrays.fill(gap, 0);
        int front = 0, rear = 0;
        q[rear++] = t;
        inq[t] = true;
        gap[0]++;
        dist[t] = 0;
        while (front < rear) {
            int u = q[front++];
            for (int i : adj[u]) {
                int v = edges[i].v;
                if (!inq[v]) {
                    q[rear++] = v;
                    inq[v] = true;
                    dist[v] = dist[u] + 1;
                    gap[dist[v]]++;
                    // No need to store the path, using arc array for current edge
                }
            }
        }

        int totalFlow = 0, low = INF, u = s;
        while (dist[s] < t) {
            boolean pushed = false;
            for (int i = arc[u]; i != -1; i = getNextEdgeIndex(adj[u], i)) {
                if (edges[i].w > 0 && dist[edges[i].v] + 1 == dist[u]) {
                    low = Math.min(low, edges[i].w);
                    pre[edges[i].v] = u;
                    u = edges[i].v;
                    if (u == t) {
                        // Augment flow along the path
                        for (int vnode = t; vnode != s; vnode = pre[vnode]) {
                            int idx = findEdgeIndex(u, pre[vnode]);
                            edges[idx].w -= low;
                            edges[idx ^ 1].w += low;
                            u = pre[vnode];
                        }
                        totalFlow += low;
                        low = INF;
                        u = s;
                    }
                    pushed = true;
                    break;
                }
            }
            if (pushed) continue;

            int minDist = t + 1;
            for (int i : adj[u]) {
                if (edges[i].w > 0 && dist[edges[i].v] < minDist) {
                    minDist = dist[edges[i].v];
                    arc[u] = i;
                }
            }

            gap[dist[u]]--;
            if (gap[dist[u]] == 0) break;
            dist[u] = minDist + 1;
            gap[dist[u]]++;
            u = pre[u];
        }
        return totalFlow;
    }

    // Helper methods to find next edge index and find edge index
    static int getNextEdgeIndex(List<Integer> list, int currentIndex) {
        int idxInList = list.indexOf(currentIndex);
        if (idxInList + 1 < list.size()) {
            return list.get(idxInList + 1);
        }
        return -1;
    }

    static int findEdgeIndex(int u, int v) {
        for (int i : adj[u]) {
            if (edges[i].v == v && edges[i].w >= 0) {
                return i;
            }
        }
        return -1;
    }
}
